# define two_sum function
two_sum &lt;- function(v, target) {
  n &lt;- length(v)
  for (i in 1:(n - 1)) {
    for (j in (i + 1):n) {
      if(v[i] + v[j] == target) {
        return(c(i, j))
      }
    }
  }
return(NULL)
}







